const $=id=>document.getElementById(id);
const now=()=>Math.round(performance.now());
const state={
 schema:'offline-interview.voice-access-coexistence.v1',
 createdAt:new Date().toISOString(),
 userAgent:navigator.userAgent,
 platform:navigator.platform||null,
 secureContext:isSecureContext,
 A:{startedAt:null,endedAt:null,text:'',inputEvents:[]},
 B:{recordingStartedAt:null,voiceStartAt:null,voiceEndAt:null,recordingStoppedAt:null,text:'',inputEvents:[],capture:{trackMuted:false,trackEnded:false,trackSettings:null,recorderError:false,state:'inactive',bytes:0,mime:''},levels:{before:[],during:[],after:[]}},
 human:{voiceAccessActuallyUsed:false,audioAudibleBeforeDuringAfter:false},
 events:[],verdict:null
};
let stream=null,recorder=null,chunks=[],ctx=null,analyser=null,raf=null,blob=null,objectUrl=null;
function logEvent(type,detail={}){state.events.push({t:now(),type,...detail});render();}
function summarize(v){if(!v.length)return{samples:0,mean:0,max:0,p05:0};const s=[...v].sort((a,b)=>a-b);return{samples:v.length,mean:v.reduce((a,b)=>a+b,0)/v.length,max:Math.max(...v),p05:s[Math.floor((s.length-1)*.05)]}}
function exportState(){const out=JSON.parse(JSON.stringify(state));for(const p of ['before','during','after'])out.B.levels[p]=summarize(state.B.levels[p]);return out}
function render(){$('log').textContent=JSON.stringify(exportState(),null,2)}
function traceInput(which,e){const target=which==='A'?state.A:state.B;target.text=e.target.value;target.inputEvents.push({t:now(),type:e.type,inputType:e.inputType||null,data:e.data??null,length:e.target.value.length,isComposing:!!e.isComposing});render()}
['beforeinput','input','change','compositionstart','compositionend'].forEach(type=>$('aText').addEventListener(type,e=>traceInput('A',e)));
['beforeinput','input','change','compositionstart','compositionend'].forEach(type=>$('bText').addEventListener(type,e=>traceInput('B',e)));
$('aStart').onclick=()=>{state.A.startedAt=now();state.A.endedAt=null;state.A.text=$('aText').value;state.A.inputEvents=[];$('aStart').disabled=true;$('aEnd').disabled=false;$('aText').focus();$('aStatus').className='status';$('aStatus').textContent='A actif — utilise maintenant Voice Access dans Réponse A.';logEvent('a_started')};
$('aEnd').onclick=()=>{state.A.endedAt=now();state.A.text=$('aText').value;const ok=state.A.text.trim().length>0;$('aStart').disabled=false;$('aEnd').disabled=true;$('aStatus').className='status '+(ok?'pass':'warn');$('aStatus').textContent=ok?'A positif — du texte a été inséré.':'A non concluant — aucun texte inséré.';logEvent('a_ended',{chars:state.A.text.length})};
function levelLoop(){if(!analyser)return;const data=new Uint8Array(analyser.fftSize);analyser.getByteTimeDomainData(data);let sum=0;for(const x of data){const v=(x-128)/128;sum+=v*v}const rms=Math.sqrt(sum/data.length);let phase='before';if(state.B.voiceStartAt!==null&&state.B.voiceEndAt===null)phase='during';else if(state.B.voiceEndAt!==null)phase='after';state.B.levels[phase].push(rms);$('liveLevel').textContent=`Niveau audio : ${rms.toFixed(4)} (${phase})`;$('meterBar').style.width=`${Math.min(100,rms*300)}%`;raf=requestAnimationFrame(levelLoop)}
async function stopGraph(){if(raf)cancelAnimationFrame(raf);raf=null;try{await ctx?.close()}catch{}ctx=null;analyser=null}
$('bRecord').onclick=async()=>{try{chunks=[];blob=null;if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null}$('audio').removeAttribute('src');state.B={recordingStartedAt:null,voiceStartAt:null,voiceEndAt:null,recordingStoppedAt:null,text:$('bText').value,inputEvents:[],capture:{trackMuted:false,trackEnded:false,trackSettings:null,recorderError:false,state:'starting',bytes:0,mime:''},levels:{before:[],during:[],after:[]}};stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});const track=stream.getAudioTracks()[0];state.B.recordingStartedAt=now();state.B.capture.trackSettings=track.getSettings?track.getSettings():null;track.onmute=()=>{state.B.capture.trackMuted=true;logEvent('track_mute')};track.onunmute=()=>logEvent('track_unmute');track.onended=()=>{state.B.capture.trackEnded=true;logEvent('track_ended')};recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onerror=e=>{state.B.capture.recorderError=true;logEvent('recorder_error',{name:e.error?.name||'',message:e.error?.message||''})};recorder.onstop=async()=>{state.B.recordingStoppedAt=now();blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});state.B.capture.state='inactive';state.B.capture.bytes=blob.size;state.B.capture.mime=blob.type;stream?.getTracks().forEach(t=>t.stop());objectUrl=URL.createObjectURL(blob);$('audio').src=objectUrl;$('bRecord').disabled=false;$('bVoiceStart').disabled=true;$('bVoiceEnd').disabled=true;$('bStop').disabled=true;$('bStatus').textContent=`B enregistré — ${Math.round(blob.size/1024)} Ko. Réécoute l’audio avant le verdict.`;logEvent('recording_stopped',{bytes:blob.size,mime:blob.type});await stopGraph()};recorder.start(500);state.B.capture.state='recording';ctx=new (window.AudioContext||window.webkitAudioContext)();await ctx.resume();const src=ctx.createMediaStreamSource(stream);analyser=ctx.createAnalyser();analyser.fftSize=1024;src.connect(analyser);levelLoop();$('bRecord').disabled=true;$('bVoiceStart').disabled=false;$('bStop').disabled=false;$('bStatus').className='status';$('bStatus').textContent='B actif — parle 5 secondes avant Voice Access.';logEvent('recording_started',{mime:recorder.mimeType||'',settings:state.B.capture.trackSettings})}catch(e){state.B.capture.recorderError=true;state.B.capture.state='error';$('bStatus').className='status fail';$('bStatus').textContent=`Échec capture : ${e.message||e}`;logEvent('recording_start_error',{name:e?.name||'',message:String(e?.message||e)})}};
$('bVoiceStart').onclick=()=>{state.B.voiceStartAt=now();state.B.voiceEndAt=null;$('bVoiceStart').disabled=true;$('bVoiceEnd').disabled=false;$('bText').focus();$('bStatus').textContent='Fenêtre Voice Access active — dicte maintenant dans Réponse B pendant 10–15 secondes.';logEvent('voice_access_window_start')};
$('bVoiceEnd').onclick=()=>{state.B.voiceEndAt=now();state.B.text=$('bText').value;$('bVoiceEnd').disabled=true;$('bStatus').textContent='Fenêtre terminée — parle encore 5 secondes puis arrête B.';logEvent('voice_access_window_end',{chars:state.B.text.length})};
$('bStop').onclick=()=>{if(recorder?.state==='recording'){state.B.capture.state='stopping';logEvent('stop_requested');recorder.stop()}};
$('finalize').onclick=()=>{state.A.text=$('aText').value;state.B.text=$('bText').value;state.human.voiceAccessActuallyUsed=$('voiceActuallyUsed').checked;state.human.audioAudibleBeforeDuringAfter=$('audioOk').checked;const A=state.A.text.trim().length>0,B=state.B.text.trim().length>0,c=state.B.capture,L={before:summarize(state.B.levels.before),during:summarize(state.B.levels.during),after:summarize(state.B.levels.after)};const intact=!c.trackMuted&&!c.trackEnded&&!c.recorderError&&c.bytes>0;const duringEnergy=L.during.samples>=5&&L.during.mean>0.003;const beforeEnergy=L.before.samples>=5&&L.before.mean>0.003;const afterEnergy=L.after.samples>=5&&L.after.mean>0.003;let code,msg,cls;if(!A){code='INCONCLUSIVE_VOICE_ACCESS_BASELINE';msg='INCONCLUSIVE — Voice Access n’est pas prouvé sans enregistrement.';cls='warn'}else if(!state.human.voiceAccessActuallyUsed){code='HOLD_VOICE_ACCESS_CONFIRMATION_REQUIRED';msg='HOLD — du texte existe, mais il faut confirmer qu’il a été dicté avec Voice Access.';cls='warn'}else if(A&&!B){code='FAIL_FAST_VOICE_ACCESS_BLOCKED_DURING_CAPTURE';msg='FAIL_FAST — Voice Access fonctionne sans capture mais n’insère pas de texte pendant l’enregistrement maître.';cls='fail'}else if(B&&!intact){code='FAIL_FAST_MASTER_CAPTURE_INTERRUPTED';msg='FAIL_FAST — la capture maître a subi mute/end/error pendant le scénario.';cls='fail'}else if(B&&intact&&!(beforeEnergy&&duringEnergy&&afterEnergy)){code='FAIL_FAST_MASTER_AUDIO_ENERGY_GAP';msg='FAIL_FAST — l’énergie audio n’est pas démontrée avant, pendant et après Voice Access.';cls='fail'}else if(B&&intact&&beforeEnergy&&duringEnergy&&afterEnergy&&!state.human.audioAudibleBeforeDuringAfter){code='HUMAN_AUDIO_REVIEW_REQUIRED';msg='HOLD — coexistence technique positive; réécoute et confirme l’intelligibilité continue.';cls='warn'}else if(A&&B&&state.human.voiceAccessActuallyUsed&&intact&&beforeEnergy&&duringEnergy&&afterEnergy&&state.human.audioAudibleBeforeDuringAfter){code='PASS_CANDIDATE_ANDROID_VOICE_ACCESS';msg='PASS_CANDIDATE — Voice Access et l’audio maître coexistent sur ce téléphone/navigateur pour ce test.';cls='pass'}else{code='INCONCLUSIVE';msg='INCONCLUSIVE — preuve insuffisante.';cls='warn'}state.verdict={code,message:msg,computedAt:now(),levels:L,captureIntact:intact};$('verdict').className='status '+cls;$('verdict').textContent=msg;logEvent('verdict',{code});render()};
$('copy').onclick=async()=>{render();try{await navigator.clipboard.writeText($('log').textContent);$('copy').textContent='JSON copié ✓';setTimeout(()=>$('copy').textContent='Copier le JSON',1800)}catch{alert('Copie impossible : sélectionne le JSON manuellement.')}};
logEvent('ready');
